package com.fuelflex.platform.operations.blocktwo;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
import com.fuelflex.platform.common.security.AuthorizationService;import com.fuelflex.platform.depot.entity.Depot;import com.fuelflex.platform.fuelmeter.entity.FuelMeter;import com.fuelflex.platform.operations.dto.DailyOperationsDtos.*;import com.fuelflex.platform.operations.entity.*;import com.fuelflex.platform.operations.repository.*;import com.fuelflex.platform.operations.service.*;import com.fuelflex.platform.organization.entity.Organization;import com.fuelflex.platform.product.entity.Product;import com.fuelflex.platform.pump.entity.Pump;import com.fuelflex.platform.reception.repository.ReceptionStockBalanceRepository;import com.fuelflex.platform.role.entity.Role;import com.fuelflex.platform.sale.entity.*;import com.fuelflex.platform.sale.repository.*;import com.fuelflex.platform.station.entity.Station;import com.fuelflex.platform.station.service.StationAccessService;import com.fuelflex.platform.tank.entity.Tank;import com.fuelflex.platform.tank.repository.TankRepository;import com.fuelflex.platform.user.entity.User;
@ExtendWith(MockitoExtension.class)class DailyOperationsServiceTest{
 @Mock AuthorizationService auth;@Mock OperationalDayRepository days;@Mock DailyExpenseRepository expenses;@Mock TankGaugeReadingRepository gauges;@Mock ShiftReconciliationRepository recs;@Mock FuelSaleRepository sales;@Mock TankRepository tanks;@Mock ReceptionStockBalanceRepository inbound;@Mock SaleStockMovementRepository outbound;@Mock MeteredStockMovementRepository metered;@Mock TankReturnSourceMovementRepository returnSources;@Mock TankReturnRepository returns;@Mock TankReturnStockMovementRepository returnMovements;@Mock OperationalDaySummaryRepository summaries;@Mock StationAccessService access;@Mock SupervisorOperationalNotifier notifier;DailyOperationsServiceImpl service;User manager;OperationalDay day;Tank tank;
 @BeforeEach void setup(){service=new DailyOperationsServiceImpl(auth,days,expenses,gauges,recs,sales,tanks,inbound,outbound,metered,returnSources,returns,returnMovements,summaries,access,notifier);Organization org=new Organization();org.setId(UUID.randomUUID());org.setDefaultCurrency("CDF");Station station=new Station();station.setId(UUID.randomUUID());station.setName("S");station.setOrganization(org);manager=user(org,"MANAGER");day=new OperationalDay();day.setId(UUID.randomUUID());day.setOrganization(org);day.setStation(station);day.setStatus(OperationalStatus.OPEN);Depot depot=new Depot();depot.setStation(station);tank=new Tank();tank.setId(UUID.randomUUID());tank.setName("T");tank.setDepot(depot);tank.setMaximumLevelLiters(new BigDecimal("2000.000"));when(auth.getAuthenticatedUser()).thenReturn(manager);when(days.findByIdAndOrganizationId(day.getId(),org.getId())).thenReturn(Optional.of(day));}
 @Test void gaugeStockAddsTankReturnsToReceptionMinusSales(){when(tanks.findByIdAndDepotStationId(tank.getId(),day.getStation().getId())).thenReturn(Optional.of(tank));when(inbound.sumInboundByTankId(tank.getId())).thenReturn(new BigDecimal("1000"));when(outbound.sumOutboundByTankId(tank.getId())).thenReturn(new BigDecimal("100"));when(returnMovements.sumInboundByTankId(tank.getId())).thenReturn(new BigDecimal("5"));when(gauges.saveAndFlush(any())).thenAnswer(i->{TankGaugeReading g=i.getArgument(0);g.setId(UUID.randomUUID());return g;});GaugeResponse r=service.addGauge(day.getId(),new GaugeRequest(tank.getId(),new BigDecimal("905"),null));assertThat(r.theoreticalStock()).isEqualByComparingTo("905.000");assertThat(r.stockVariance()).isEqualByComparingTo("0.000");}
 @Test void rjvSeparatesReturnFromSalesAndCash(){when(sales.findByOperationalDayIdOrderBySoldAtAsc(day.getId())).thenReturn(List.of());when(recs.findByShiftAssignmentOperationalDayIdOrderByShiftAssignmentOpenedAtAsc(day.getId())).thenReturn(List.of());when(expenses.findByOperationalDayIdOrderByCreatedAtAsc(day.getId())).thenReturn(List.of());when(gauges.findByOperationalDayIdOrderByTankNameAsc(day.getId())).thenReturn(List.of());when(returns.sumOpenQuantityByDayId(day.getId())).thenReturn(new BigDecimal("5"));RjvResponse r=service.rjv(day.getId());assertThat(r.tankReturnVolume()).isEqualByComparingTo("5.000");assertThat(r.totalSalesAmount()).isZero();assertThat(r.expectedCash()).isZero();}
 @Test void rjvCombinesClosedReconciliationWithOpenPosSalesWithoutCountingClosedSaleTwice(){Product product=new Product();product.setId(UUID.randomUUID());product.setName("Diesel");tank.setProduct(product);Pump pump=new Pump();pump.setId(UUID.randomUUID());pump.setName("P1");FuelMeter meter=new FuelMeter();meter.setId(UUID.randomUUID());meter.setName("M1");meter.setPump(pump);User attendant=user(manager.getOrganization(),"PUMP_ATTENDANT");attendant.setFirstName("A");attendant.setLastName("Closed");PumpShiftAssignment closed=new PumpShiftAssignment();closed.setId(UUID.randomUUID());closed.setOperationalDay(day);closed.setPumpAttendant(attendant);closed.setFuelMeter(meter);closed.setStatus(OperationalStatus.CLOSED);ShiftReconciliation rec=new ShiftReconciliation();rec.setId(UUID.randomUUID());rec.setShiftAssignment(closed);rec.setSourceTank(tank);rec.setProduct(product);rec.setOpeningIndex(BigDecimal.ZERO);rec.setClosingIndex(new BigDecimal("100"));rec.setMeteredVolume(new BigDecimal("100"));rec.setCashVolume(new BigDecimal("70"));rec.setCashUnitPrice(new BigDecimal("2"));rec.setCashAmount(new BigDecimal("140"));rec.setCreditVolume(new BigDecimal("20"));rec.setCreditUnitPrice(new BigDecimal("3"));rec.setCreditAmount(new BigDecimal("60"));rec.setTankReturnVolume(new BigDecimal("10"));rec.setTotalSoldVolume(new BigDecimal("90"));rec.setTurnover(new BigDecimal("200"));rec.setAccountedVolume(new BigDecimal("100"));rec.setVolumeVariance(BigDecimal.ZERO);PumpShiftAssignment open=new PumpShiftAssignment();open.setStatus(OperationalStatus.OPEN);FuelSale openSale=sale(open,attendant,meter,product,new BigDecimal("5"),new BigDecimal("10"));FuelSale closedSale=sale(closed,attendant,meter,product,new BigDecimal("70"),new BigDecimal("140"));when(sales.findByOperationalDayIdOrderBySoldAtAsc(day.getId())).thenReturn(List.of(closedSale,openSale));when(recs.findByShiftAssignmentOperationalDayIdOrderByShiftAssignmentOpenedAtAsc(day.getId())).thenReturn(List.of(rec));when(expenses.findByOperationalDayIdOrderByCreatedAtAsc(day.getId())).thenReturn(List.of());when(gauges.findByOperationalDayIdOrderByTankNameAsc(day.getId())).thenReturn(List.of());when(returns.sumOpenQuantityByDayId(day.getId())).thenReturn(new BigDecimal("2"));RjvResponse r=service.rjv(day.getId());assertThat(r.cashVolume()).isEqualByComparingTo("75.000");assertThat(r.cashAmount()).isEqualByComparingTo("150.000");assertThat(r.creditVolume()).isEqualByComparingTo("20.000");assertThat(r.tankReturnVolume()).isEqualByComparingTo("12.000");assertThat(r.totalSalesAmount()).isEqualByComparingTo("210.000");assertThat(r.accountedVolume()).isEqualByComparingTo("100.000");assertThat(r.volumeVariance()).isZero();assertThat(r.cashVolume()).isNotEqualByComparingTo("145.000");}
 @Test void historicalClosedDayHasNoInventedPhysicalCashOrStatus(){RjvResponse r=closedReport(false,"0");assertThat(r.cashReconciliationAvailable()).isFalse();assertThat(r.physicalReferenceAmount()).isNull();assertThat(r.physicalUsdAmount()).isNull();assertThat(r.usdExchangeRate()).isNull();assertThat(r.observedCashAmount()).isNull();assertThat(r.cashVariance()).isNull();assertThat(r.cashStatus()).isNull();assertThat(r.cashGrossExpected()).isEqualByComparingTo("100.000");assertThat(r.creditAmount()).isEqualByComparingTo("50.000");assertThat(r.disbursedExpenseAmount()).isEqualByComparingTo("10.000");}
 @Test void newClosedDayWithZeroVarianceIsConform(){RjvResponse r=closedReport(true,"0");assertThat(r.cashReconciliationAvailable()).isTrue();assertThat(r.cashStatus()).isEqualTo("CONFORME");}
 @Test void newClosedDayWithNegativeVarianceIsDeficit(){assertThat(closedReport(true,"-5").cashStatus()).isEqualTo("DEFICIT");}
 @Test void newClosedDayWithPositiveVarianceIsExcess(){assertThat(closedReport(true,"5").cashStatus()).isEqualTo("EXCEDENT");}
 private RjvResponse closedReport(boolean available,String variance){day.setStatus(OperationalStatus.CLOSED);OperationalDaySummary x=new OperationalDaySummary();x.setCashVolume(new BigDecimal("40"));x.setCashAmount(new BigDecimal("100"));x.setCreditVolume(new BigDecimal("20"));x.setCreditAmount(new BigDecimal("50"));x.setTankReturnVolume(BigDecimal.ZERO);x.setSoldVolume(new BigDecimal("60"));x.setMeteredVolume(new BigDecimal("60"));x.setAccountedVolume(new BigDecimal("60"));x.setVolumeVariance(BigDecimal.ZERO);x.setExpenseAmount(new BigDecimal("10"));x.setExpectedCash(new BigDecimal("100"));x.setExpectedNetCash(new BigDecimal("90"));x.setReferenceCurrency("CDF");x.setCashGrossExpected(new BigDecimal("100"));x.setDisbursedExpenseAmount(new BigDecimal("10"));x.setCashNetExpected(new BigDecimal("90"));x.setCashReconciliationAvailable(available);x.setPhysicalReferenceAmount(new BigDecimal("90"));x.setPhysicalUsdAmount(BigDecimal.ZERO);x.setUsdExchangeRate(new BigDecimal("2850"));x.setConvertedUsdAmount(BigDecimal.ZERO);x.setObservedCashAmount(new BigDecimal("90").add(new BigDecimal(variance)));x.setCashVariance(new BigDecimal(variance));x.setTheoreticalStock(BigDecimal.ZERO);x.setPhysicalStock(BigDecimal.ZERO);x.setInternalConsumptionVolume(BigDecimal.ZERO);x.setInternalConsumptionAmount(BigDecimal.ZERO);when(summaries.findByOperationalDayId(day.getId())).thenReturn(Optional.of(x));when(sales.findByOperationalDayIdOrderBySoldAtAsc(day.getId())).thenReturn(List.of());when(recs.findByShiftAssignmentOperationalDayIdOrderByShiftAssignmentOpenedAtAsc(day.getId())).thenReturn(List.of());when(expenses.findByOperationalDayIdOrderByCreatedAtAsc(day.getId())).thenReturn(List.of());when(gauges.findByOperationalDayIdOrderByTankNameAsc(day.getId())).thenReturn(List.of());return service.rjv(day.getId());}
 private FuelSale sale(PumpShiftAssignment shift,User attendant,FuelMeter meter,Product product,BigDecimal quantity,BigDecimal amount){FuelSale sale=new FuelSale();sale.setShiftAssignment(shift);sale.setPumpAttendant(attendant);sale.setFuelMeter(meter);sale.setProduct(product);sale.setSaleType(SaleType.CASH);sale.setStatus(SaleStatus.EFFECTIVE);sale.setQuantity(quantity);sale.setTotalAmount(amount);return sale;}
 private User user(Organization o,String c){Role r=new Role();r.setCode(c);r.setActive(true);User u=new User();u.setId(UUID.randomUUID());u.setOrganization(o);u.setEnabled(true);u.setRoles(Set.of(r));return u;}
}
